    },
    {
      "hunk_id": "H007",
      "decision": "SOL",
      "reason": "“Anticipate” preserves the meaning of expecting the attack."
    },
    {
      "hunk_id": "H008",
      "decision": "SOL",
      "reason": "The recast keeps the sliced-up ground and Jin’s evasion without changing the action."
    },
    {
      "hunk_id": "H009",
      "decision": "SOL",
      "reason": "Naming Morgoth clarifies whose voice continues without changing the viewpoint."
    },
    {
      "hunk_id": "H010",
      "decision": "SOL",
