    },
    {
      "hunk_id": "H011",
      "decision": "SOL",
      "reason": "“Refusing to face” preserves the sense that he had been avoiding the truth."
    },
    {
      "hunk_id": "H012",
      "decision": "BASE",
      "reason": "The source says the magic is surrounding him now; SOL drops that timing cue."
    },
    {
      "hunk_id": "H013",
      "decision": "SOL",
      "reason": "The recast preserves that Morgoth’s courtesy served his own dignity, not his opponent."
    },
    {
      "hunk_id": "H014",
      "decision": "BASE",
      "reason": "SOL drops the contemptuous address in “네놈”; BASE preserves that attitude with “you bastard.”"
    },
    {
      "hunk_id": "H015",
      "decision": "SOL",
      "reason": "“Within a radius … around” states the area clearly, and “him” keeps Jin as the target."
    },
    {
      "hunk_id": "H016",
      "decision": "BASE",
      "reason": "The source describes a piercing sound, singular; SOL changes it to multiple whistles."
    },
    {
      "hunk_id": "H017",
      "decision": "SOL",
      "reason": "“Stems” and “from end to end” express the vines’ thickness and the thorns covering them."
    },
    {
      "hunk_id": "H018",
      "decision": "SOL",
      "reason": "The reordered sentence keeps the contrast with sunlight and the vines’ power."
    },
    {
      "hunk_id": "H019",
      "decision": "BASE",
      "reason": "The source includes a sharp sound before he steadies his breathing; deleting it drops that beat."
    },
    {
      "hunk_id": "H020",
      "decision": "BASE",
      "reason": "SOL adds that he stepped forward, a direction not specified in the source."
    },
    {
      "hunk_id": "H021",
      "decision": "SOL",
      "reason": "“Reaching the edge of its realm” reflects the source’s image of approaching the realm’s limit."
    },
    {
      "hunk_id": "H022",
      "decision": "SOL",
      "reason": "The recast preserves the line expanding into a vast circle."
    },
    {
      "hunk_id": "H023",
      "decision": "SOL",
      "reason": "SOL carries the ash and embers into the following sentence rather than dropping the image."
    },
    {
      "hunk_id": "H024",
      "decision": "BASE",
      "reason": "The source says Jin stood tall and alone; SOL drops the emphasis on his upright, imposing stance."
    },
    {
      "hunk_id": "H025",
      "decision": "BASE",
      "reason": "SOL drops the comparison between the spells’ power and the dazzling flashes; BASE retains it."
    },
    {
      "hunk_id": "H026",
      "decision": "BASE",
      "reason": "The source specifies one direction; SOL changes this to one place."
    },
    {
      "hunk_id": "H027",
      "decision": "SOL",
      "reason": "“A weight of dozens of tons” preserves the force, and the revised sentence reads naturally."
    },
    {
      "hunk_id": "H028",
      "decision": "SOL",
      "reason": "“Shining down on” keeps the spells’ light falling on Jin."
    },
    {
      "hunk_id": "H029",
      "decision": "BASE",
      "reason": "The source imagines Jin standing there instead of Morgoth; “left standing” adds a survival or victory implication."
    },
    {
      "hunk_id": "H030",
      "decision": "SOL",
      "reason": "“Those were different” correctly agrees with the two aspects being compared."
    },
    {
      "hunk_id": "H031",
      "decision": "SOL",
      "reason": "The possessive recast preserves the comparison and avoids the baseline’s awkward phrasing."
    },
    {
      "hunk_id": "H032",
      "decision": "SOL",
      "reason": "The recast keeps the difference in their power as the reason the battle and the world’s fate were decided."
    },
    {
      "hunk_id": "H033",
      "decision": "BASE",
      "reason": "SOL omits the source’s paired actions of emptying and pouring out his power."
    },
    {
      "hunk_id": "H034",
      "decision": "SOL",
      "reason": "The recast preserves both reasons for the Breath’s reduced range and destructive power."
    },
    {
      "hunk_id": "H035",
      "decision": "SOL",
      "reason": "“Resilient” conveys the hero’s toughness without turning 강인 into a direct power ranking."
    },
    {
      "hunk_id": "H036",
      "decision": "BASE",
      "reason": "The source says the power finally became a flash; SOL drops that timing and culmination."
    },
    {
      "hunk_id": "H037",
      "decision": "SOL",
      "reason": "“D immer than usual” preserves the contrast with his normal state in natural English."
    },
    {
      "hunk_id": "H038",
      "decision": "SOL",
      "reason": "“Caught in a sensation” keeps the sense without the unnatural “captured by.”"
    },
    {
      "hunk_id": "H039",
      "decision": "SOL",
      "reason": "“The meaning of those two characters” preserves the No-self reference without the awkward “contained in.”"
    },
    {
      "hunk_id": "H040",
      "decision": "SOL",
      "reason": "The recast preserves that he experiences again a sensation absent since that day."
    }
  ]
}

